import{_ as e}from"./chunks/eye.BRl0ZGNz.js";import{_ as a}from"./chunks/trash.D6Oim2A3.js";import{_ as n,c as s,o as i,ag as l}from"./chunks/framework.DZ_cNctr.js";const r="/docs/icons/info.svg",o="/docs/icons/plus.svg",c="/docs/icons/copy.svg",w=JSON.parse('{"title":"Analytics & Phenotyping — Find Nuclei Viewer","description":"Load per-object measurement CSVs to color segmentation labels by column (heatmap or category), filter objects by value, and build named phenotype populations with composable filter conditions.","frontmatter":{"title":"Analytics & Phenotyping — Find Nuclei Viewer","description":"Load per-object measurement CSVs to color segmentation labels by column (heatmap or category), filter objects by value, and build named phenotype populations with composable filter conditions."},"headers":[],"relativePath":"guides/analytics-phenotyping.md","filePath":"guides/analytics-phenotyping.md"}'),h={name:"guides/analytics-phenotyping.md"};function d(p,t,u,g,m,b){return i(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="analytics-phenotyping" tabindex="-1">Analytics &amp; Phenotyping <a class="header-anchor" href="#analytics-phenotyping" aria-label="Permalink to &quot;Analytics &amp; Phenotyping&quot;">​</a></h1><p>Load per-object measurements from a CSV, color your segmentation by any column, filter objects by range or value, and build named <strong>phenotype</strong> groups to classify cell populations.</p><p>The short version: analytics lives <strong>inside a label</strong>. You load a table that maps object ID → measurements, and the viewer colors the label mask by any column. Everything you configure is per-label — different labels can have different CSVs, different coloring, different phenotypes.</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>analytics-overview.png</code> — Wide shot: cells colored by phenotype groups (Small/Mid/Large) on the canvas, legend overlay bottom-right, Labels tab expanded showing the Analytics section in the sidebar. </div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A segmentation label loaded on the image (either embedded in the OME-Zarr or added via <strong>Add Local</strong> / <strong>Add URL</strong>).</li><li>A CSV of per-object measurements with an object-ID column that matches the label&#39;s pixel values (most CellProfiler / FIJI / QuPath exports work out of the box).</li><li>Chrome or Edge — CSV loading uses the File System Access API. Firefox and Safari don&#39;t yet support the file picker required here.</li></ul><h2 id="loading-a-csv" tabindex="-1">Loading a CSV <a class="header-anchor" href="#loading-a-csv" aria-label="Permalink to &quot;Loading a CSV&quot;">​</a></h2><ol><li>Open the <strong>Labels</strong> tab and click a label row to expand its detail panel.</li><li>Inside the expanded detail, find the <strong>ANALYTICS</strong> section.</li><li>Click <strong>Load CSV</strong> (first time) or <strong>Replace</strong> (if one&#39;s already loaded).</li><li>Pick your file. The viewer parses it, profiles every column, and shows a summary: <code>filename · N obj · M col</code>.</li></ol><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>analytics-section.png</code> — The ANALYTICS section header + filename summary &quot;nuclei.csv · 329 obj · 12 col&quot; with Replace / Clear buttons, and the FILTERS / PHENOTYPES stubs below. </div><h3 id="object-id-auto-detection" tabindex="-1">Object-ID auto-detection <a class="header-anchor" href="#object-id-auto-detection" aria-label="Permalink to &quot;Object-ID auto-detection&quot;">​</a></h3><p>The viewer tries these column names in order: <code>objectid</code>, <code>object_id</code>, <code>ObjectId</code>, <code>object</code>, <code>label</code>, <code>label_id</code>, <code>id</code>. If it finds exactly one match, it uses that. If it finds multiple candidates, it shows an inline picker asking which column to use. If it finds none, it falls back to row index — row 1 = object 1, row 2 = object 2, matching CellProfiler / FIJI / QuPath default-export conventions.</p><h3 id="inspecting-the-columns" tabindex="-1">Inspecting the columns <a class="header-anchor" href="#inspecting-the-columns" aria-label="Permalink to &quot;Inspecting the columns&quot;">​</a></h3><p>Click the <img src="'+r+'" class="fn-icon" alt="info"> info button next to the filename to open a table summary:</p><ul><li><strong>Numeric columns</strong>: min, max, mean, standard deviation, null count</li><li><strong>String columns</strong>: number of unique values (capped at 500)</li><li>Detected object-ID column is flagged at the top.</li></ul><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>analytics-info-modal.png</code> — TableInfoModal showing the column list with types and statistics. </div><div class="tip custom-block"><p class="custom-block-title">File formats</p><p>CSV is the common path. Tab- or semicolon-delimited tables work too — the parser auto-detects the separator. Parquet and HTTPS-hosted URLs are on the roadmap — see the <a href="./analytics-bundle.html">Analytics Bundle Spec</a> for the full directory contract the Find Nuclei Analysis Tool will emit.</p></div><h2 id="color-by-column" tabindex="-1">Color by column <a class="header-anchor" href="#color-by-column" aria-label="Permalink to &quot;Color by column&quot;">​</a></h2><p>With analytics loaded, open the label&#39;s <strong>color swatch popover</strong> (the coloured square on the label row). Three coloring modes become available:</p><ul><li><strong>Solid</strong> — one color for everything (default, no analytics needed)</li><li><strong>Random</strong> — hash object ID → color (no analytics needed)</li><li><strong>Heatmap</strong> — numeric column → color ramp</li><li><strong>Category</strong> — string column → distinct color per value</li></ul><h3 id="heatmap-numeric-columns" tabindex="-1">Heatmap (numeric columns) <a class="header-anchor" href="#heatmap-numeric-columns" aria-label="Permalink to &quot;Heatmap (numeric columns)&quot;">​</a></h3><p>Pick a numeric column from the dropdown. The viewer colors every object on the canvas by its value along a scientific color ramp.</p><p>Available ramps:</p><ul><li><strong>viridis</strong> — perceptually uniform, default, handles most data</li><li><strong>magma</strong>, <strong>inferno</strong>, <strong>plasma</strong> — darker low, brighter high</li><li><strong>coolwarm</strong> — diverging, useful for zero-centered measurements</li><li><strong>turbo</strong> — high-contrast rainbow</li></ul><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>analytics-heatmap.png</code> — Canvas view of nuclei colored by area_px heatmap. Legend in the corner shows the ramp gradient with min/max labels. </div><p>Below the column and ramp controls, a histogram of the column&#39;s values appears with a dual-range slider. Drag the handles to <strong>override the display min/max</strong> — useful when a handful of outliers compress the interesting signal. The legend card reflects your override in real time.</p><h3 id="category-string-columns" tabindex="-1">Category (string columns) <a class="header-anchor" href="#category-string-columns" aria-label="Permalink to &quot;Category (string columns)&quot;">​</a></h3><p>Pick a string column. Each unique value gets a distinct color from a deterministic palette (same value → same color across reloads). The canvas re-colors every object by its category, and a legend card below the scale bar lists color ■ value pairs.</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>analytics-category.png</code> — Canvas colored by a string column, legend showing color ■ name pairs for each unique category. </div><p>For columns with many unique values, the legend caps at 12 rows and shows &quot;+N more&quot;.</p><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><p>Below the color-by section, a <strong>FILTERS</strong> panel hides objects that don&#39;t match your conditions. Filters don&#39;t change the coloring — they just remove non-matching objects from the canvas.</p><p>Click <img src="'+o+'" class="fn-icon" alt="add"> <strong>Add filter</strong> and pick a column from the popover. The filter&#39;s UI depends on the column type:</p><ul><li><strong>Numeric</strong>: histogram + dual-range slider. The range you pick is inclusive; objects outside it become invisible.</li><li><strong>String</strong>: checkbox grid of unique values, all selected by default. Uncheck the values you want to exclude.</li></ul><p>Multiple filters <strong>compose with AND</strong> — an object must pass every active filter to stay visible. Each filter row has a remove control and a collapse control to hide its histogram when you want a compact view.</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>analytics-filters.png</code> — FILTERS section with two filter rows — one numeric with a range slider, one string with checkboxes. </div><div class="tip custom-block"><p class="custom-block-title">Filters are independent of coloring</p><p>You can color by <code>area_px</code> (heatmap) while filtering by <code>is_mitotic</code> (string). The two settings compose cleanly — color reflects the data dimension you care about, filters remove the objects you don&#39;t.</p></div><h2 id="phenotypes" tabindex="-1">Phenotypes <a class="header-anchor" href="#phenotypes" aria-label="Permalink to &quot;Phenotypes&quot;">​</a></h2><p>A <strong>phenotype</strong> is a named, coloured group of filter conditions. Think of it as a named bucket: &quot;Small cells with high marker X&quot;, &quot;Cells at the tumor-stroma boundary&quot;, &quot;Cells that entered mitosis.&quot; Phenotypes compose on top of the same filter machinery above — but each phenotype has its own color, name, and visibility.</p><p>When at least one phenotype exists, the canvas switches to <strong>phenotype coloring</strong>: every object gets the color of the first phenotype it matches. Objects that match nothing show in gray (toggleable) or hide entirely.</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>analytics-phenotypes.png</code> — PHENOTYPES section with 3 groups (Small / Mid / Large), each with a colored swatch, <img src="'+e+'" class="fn-icon" alt="show"> toggle, name, filter count badge, <img src="'+a+'" class="fn-icon" alt="delete">. </div><h3 id="creating-a-phenotype" tabindex="-1">Creating a phenotype <a class="header-anchor" href="#creating-a-phenotype" aria-label="Permalink to &quot;Creating a phenotype&quot;">​</a></h3><p>Click <img src="'+o+'" class="fn-icon" alt="add"> <strong>Add phenotype</strong>. A new group appears with a default color, name, and no filters. Click the name to rename it. Click the swatch to pick a colour. Add filters inside the group the same way you add global filters — the difference is they belong to this group alone.</p><p>The first phenotype you create <strong>auto-flips</strong> the label&#39;s coloring to phenotype mode. You don&#39;t need to manually switch — the viewer assumes &quot;you just created a phenotype, you probably want to see it.&quot;</p><h3 id="reordering-first-match-wins" tabindex="-1">Reordering (first-match-wins) <a class="header-anchor" href="#reordering-first-match-wins" aria-label="Permalink to &quot;Reordering (first-match-wins)&quot;">​</a></h3><p>Phenotype groups evaluate <strong>top to bottom</strong>. The first group an object matches wins the color — if you have overlapping definitions, the order of groups matters.</p><p>Drag the grip handle on the left of each phenotype to reorder. Duplicate a group with the <img src="'+c+'" class="fn-icon" alt="duplicate"> copy icon if you need a similar one with slight tweaks — filters and color copy over, name gets &quot;(copy)&quot; appended.</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>analytics-phenotype-drag.png</code> — Phenotype row mid-drag, showing the grip handle and the drop target indicator. </div><h3 id="show-unmatched-objects" tabindex="-1">Show unmatched objects <a class="header-anchor" href="#show-unmatched-objects" aria-label="Permalink to &quot;Show unmatched objects&quot;">​</a></h3><p>A checkbox below the phenotype list: <strong>Show unmatched objects (gray)</strong>. Objects that match no phenotype either:</p><ul><li>Render in gray (checkbox on) — useful to see the full context</li><li>Hide entirely (checkbox off) — useful to focus only on classified cells</li></ul><h3 id="assigned-vs-palette-colors" tabindex="-1">Assigned vs palette colors <a class="header-anchor" href="#assigned-vs-palette-colors" aria-label="Permalink to &quot;Assigned vs palette colors&quot;">​</a></h3><p>A <strong>Colors</strong> toggle switches between two coloring schemes:</p><ul><li><strong>Assigned</strong>: every phenotype uses its own custom color — the one you picked on its swatch.</li><li><strong>Palette</strong>: colors come from the built-in Tableau10 categorical palette, by position in the list. Reordering changes the colors.</li></ul><p>Use <strong>Palette</strong> when you&#39;re drafting and want colors to come for free; switch to <strong>Assigned</strong> when you&#39;ve finalized your palette and want every group to keep a specific hue across sessions.</p><h2 id="the-canvas-legend" tabindex="-1">The canvas legend <a class="header-anchor" href="#the-canvas-legend" aria-label="Permalink to &quot;The canvas legend&quot;">​</a></h2><p>Whenever any color viz is active (heatmap, category, or phenotype), a legend card appears above the scale bar in the bottom-right. It&#39;s read-only — it exists so someone looking at the image understands what the colors mean.</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>analytics-legend.png</code> — Bottom-right of canvas: the legend card with phenotype colours and names, stacked above the heatmap ramp bar for another label, above the scale bar. </div><p>Multiple labels can show legends at once — one card per label, stacked. Hidden labels&#39; cards disappear automatically; toggle visibility via the <img src="'+e+'" class="fn-icon" alt="visibility"> icon on the label row to control the overlay.</p><h2 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h2><p>Analytics data, visualizations, filters, and phenotypes all persist to the browser&#39;s IndexedDB, keyed by the image&#39;s ZARR URL / local folder handle. Reload the page, reopen the image — your CSV is still loaded, your heatmap is still active, your phenotypes are still in place.</p><p>The URL query string encodes channel + zoom + selection state, but <strong>not</strong> analytics data itself (CSVs can be large). The URL is enough to navigate back to your view; the local browser handles the CSV.</p><h2 id="mobile" tabindex="-1">Mobile <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Mobile&quot;">​</a></h2><p>Analytics and phenotype sections are <strong>hidden on phone-width viewports</strong>. The underlying reason: local CSV selection requires the Chrome/Edge File System Access API, which isn&#39;t available on mobile. Tablets show the full desktop UI.</p><p>URL-based analytics (the HTTPS-hosted roadmap item) will unblock phone viewing of pre-built phenotype configurations — once shipped, mobile users will be able to receive a shared link and see the phenotype-coloured view, just without the ability to tweak the CSV.</p><h2 id="gotchas" tabindex="-1">Gotchas <a class="header-anchor" href="#gotchas" aria-label="Permalink to &quot;Gotchas&quot;">​</a></h2><p><strong>Object-ID alignment.</strong> CSVs from different tools start counting from different bases. CellProfiler&#39;s <code>ObjectNumber</code> is 1-based, QuPath&#39;s detection IDs are often hash-style, napari&#39;s <code>label_id</code> matches the underlying <code>regionprops</code> convention. If objects aren&#39;t coloring at all after load, open the info modal and check: the detected object-ID column should match your label&#39;s pixel values.</p><p><strong>String columns with &gt; 500 unique values</strong> are truncated for performance. Category coloring still works, but the legend caps at 12 rows.</p><p><strong>Mixed-type columns</strong> — if any cell parses as string, the whole column is treated as string. You can&#39;t heatmap a column that accidentally has &quot;NA&quot; sprinkled through numeric values; clean up exports or filter first.</p><p><strong>Hidden labels don&#39;t contribute a legend card.</strong> If the legend isn&#39;t appearing, check that the label is visible (<img src="'+e+'" class="fn-icon" alt="visibility"> icon on the label row). We treat hidden labels as &quot;the user doesn&#39;t want this on screen&quot; and skip the legend card accordingly.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./annotations.html">Annotations</a> — annotate regions of interest on top of the same image</li><li><a href="./sharing.html">Sharing Views</a> — URL state captures the current view for reviewer handoff</li></ul>',71)])])}const k=n(h,[["render",d]]);export{w as __pageData,k as default};
